 4	final class CycleDetector {
 5	    private final DirectedGraph graph;
 6	    private final int[] indegree;
 7	    private final Queue<Integer> zeroIndegreeVertices;
 8	    private int visitedCount;
 9	
10	    private CycleDetector(DirectedGraph graph) {
11	        this.graph = graph;
12	        this.indegree = graph.indegreeSnapshot();
13	        this.zeroIndegreeVertices = collectZeroIndegreeVertices(indegree);
14	    }
15	
16	    static boolean hasCycle(DirectedGraph graph) {
17	        return new CycleDetector(graph).containsCycle();
18	    }
19	
20	    private boolean containsCycle() {
21	        while (!zeroIndegreeVertices.isEmpty()) {
22	            processNextVertex();
23	        }
24	        return visitedCount != graph.vertexCount();
25	    }
26	
27	    private void processNextVertex() {
28	        int vertex = zeroIndegreeVertices.poll();
29	        visitedCount++;
30	
31	        for (int neighbor : graph.neighborsOf(vertex)) {
32	            decrementIndegree(neighbor);
33	        }
34	    }
35	
36	    private void decrementIndegree(int vertex) {
37	        indegree[vertex]--;
38	        if (indegree[vertex] == 0) {
39	            zeroIndegreeVertices.add(vertex);
40	        }
41	    }
42	
43	    private static Queue<Integer> collectZeroIndegreeVertices(int[] indegree) {
44	        Queue<Integer> queue = new ArrayDeque<>();
45	        for (int vertex = 0; vertex < indegree.length; vertex++) {
46	            if (indegree[vertex] == 0) {
47	                queue.add(vertex);
48	            }
49	        }
50	        return queue;
51	    }
52	}

