 5	final class DirectedGraph {
 6	    private final List<List<Integer>> adjacencyList;
 7	    private final int[] indegree;
 8	
 9	    private DirectedGraph(List<List<Integer>> adjacencyList, int[] indegree) {
10	        this.adjacencyList = adjacencyList;
11	        this.indegree = indegree;
12	    }
13	
14	    public static Builder builder(int vertexCount) {
15	        return new Builder(vertexCount);
16	    }
17	
18	    public static DirectedGraph fromAdjacencyList(List<List<Integer>> adjacencyList) {
19	        Builder graph = builder(adjacencyList.size());
20	        for (int source = 0; source < adjacencyList.size(); source++) {
21	            for (int destination : adjacencyList.get(source)) {
22	                graph.addEdge(source, destination);
23	            }
24	        }
25	        return graph.build();
26	    }
27	
28	    public boolean hasCycle() {
29	        return CycleDetector.hasCycle(this);
30	    }
31	
32	    public int vertexCount() {
33	        return adjacencyList.size();
34	    }
35	
36	    public List<Integer> neighborsOf(int vertex) {
37	        validateVertex(vertex);
38	        return adjacencyList.get(vertex);
39	    }
40	
41	    public int[] indegreeSnapshot() {
42	        return indegree.clone();
43	    }
44	
45	    private void validateVertex(int vertex) {
46	        validateVertex(vertex, adjacencyList.size());
47	    }
48	
49	    private static void validateVertex(int vertex, int vertexCount) {
50	        if (vertex < 0 || vertex >= vertexCount) {
51	            throw new IndexOutOfBoundsException(
52	                    "Invalid vertex: " + vertex + " for graph size " + vertexCount);
53	        }
54	    }
55	
56	    public static final class Builder {
57	        private final List<List<Integer>> adjacencyList;
58	        private final int[] indegree;
59	
60	        private Builder(int vertexCount) {
61	            if (vertexCount < 0) {
62	                throw new IllegalArgumentException("vertexCount must be non-negative");
63	            }
64	
65	            adjacencyList = new ArrayList<>(vertexCount);
66	            indegree = new int[vertexCount];
67	            for (int vertex = 0; vertex < vertexCount; vertex++) {
68	                adjacencyList.add(new ArrayList<>());
69	            }
70	        }
71	
72	        public Builder addEdge(int source, int destination) {
73	            validateVertex(source, adjacencyList.size());
74	            validateVertex(destination, adjacencyList.size());
75	            adjacencyList.get(source).add(destination);
76	            indegree[destination]++;
77	            return this;
78	        }
79	
80	        public DirectedGraph build() {
81	            List<List<Integer>> immutableAdjacencyList = new ArrayList<>(adjacencyList.size());
82	            for (List<Integer> neighbors : adjacencyList) {
83	                immutableAdjacencyList.add(Collections.unmodifiableList(new ArrayList<>(neighbors)));
84	            }
85	
86	            return new DirectedGraph(
87	                    Collections.unmodifiableList(immutableAdjacencyList),
88	                    indegree.clone());
89	        }
90	    }
91	}

